; apx_rex2.asm -- APX extended registers through REX2 (Phases 0-1, include/iset/apx-plan.md)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23 with -mattr=+egpr, generated by
;	tests/iset/_apx_diff.py; Intel APX spec 355828-009 where it overrules
;	LLVM); a mismatch stops assembly with 'encoding mismatch'. The failure
;	cases at the end are each assembled alone by _run.ps1 (-i"FAIL=n") and
;	must stop with the quoted message. By hand:  fasm2 apx_rex2.asm apx_rex2.bin
;
; What is resolved
;	r16-r31 (with r16d/w/b/l) exist as registers. Phase 0 refused them in
;	every parser, because encoders mask register numbers to four bits and
;	silently wrote another register (add rax, r16 was add rax, rax). Now
;	x86.parse_operand accepts them in 64-bit code with APX_F, marks the
;	operand (egpr; x86.EGPR on a register number), and:
;	- x86.store_instruction writes REX2 (D5 M0 R4 X4 B4 W R3 X3 B3) for
;	  legacy map 0 and 1, dropping the 0Fh escape (M0 = 1). Intel 3.1.2.1:
;	  REX2 applies to every map 0/1 instruction with a GPR or memory operand
;	  (also x87, MMX, SSE memory forms, mov cr/dr), except XSAVE*/XRSTOR*,
;	  maps 2/3 and the reserved rows (map 0: 4x 7x Ax Ex; map 1: 3x 8x);
;	- x86.store_operand_prefix does the same for the opcodes with the
;	  register in their low bits (push/pop 50h+r, mov B8h+r, xchg 90h+r,
;	  bswap 0Fh C8h+r);
;	- every other encoder refuses the marked operand: VEX/EVEX/XOP (until
;	  APX EVEX), MPX (no CPU has MPX and APX), XSAVE*/XRSTOR* (#UD with REX2),
;	  and maps 2/3 except the instructions APX promotes to EVEX map 4
;	  (apx_promoted.asm; SSE, AES and SHA are not promoted).
;	{rex2} asks for REX2 without an extended register; like {vex3} it is a
;	preference, ignored where REX2 is not allowed. There Intel's spec
;	outranks LLVM, which writes D5 00 0F 38 F0 for {rex2} movbe ("REX2
;	followed by 0x0F triggers #UD") and D5 80 AE 20 for {rex2} xsave.
;	tests/iset/_apx_sweep.py compares every accepted extended-register form
;	of every mnemonic with llvm-mc.
;
; FAIL 1: 'APX_F or higher required'
; FAIL 2: 'APX_F or higher required'
; FAIL 3: 'bits64 or higher required'
; FAIL 4: 'disallowed combination of registers'
; FAIL 5: 'extended register not supported by this encoding'
; FAIL 6: 'extended register not supported by this encoding'
; FAIL 7: 'extended register not supported by this encoding'
; FAIL 8: 'extended register not supported by this encoding'
; FAIL 9: 'extended register not supported by this encoding'
; FAIL 10: 'extended register not supported by this encoding'
; FAIL 11: 'extended register not supported by this encoding'
; FAIL 12: 'extended register not supported by this encoding'
; FAIL 13: 'extended register not supported by this instruction'
; FAIL 14: 'extended register not supported by this instruction'
; FAIL 15: 'extended register not supported: [r16]'
; FAIL 16: 'extended register not supported: r16'
; FAIL 17: 'extended register not supported: [r16+zmm1]'
; FAIL 18: 'extended register not supported: [r16,rax]'
; FAIL 19: 'invalid address'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64
use everything

if ~ defined FAIL

	; register sizes and positions: R4 (reg), B4 (rm), W
	expect <0D5h,48h,01h,0C0h>, add rax, r16
	expect <0D5h,18h,01h,0C0h>, add r16, rax
	expect <0D5h,5Dh,01h,0FFh>, add r31, r31
	expect <0D5h,10h,01h,0C0h>, add r16d, eax
	expect <66h,0D5h,10h,01h,0C0h>, add r16w, ax
	expect <0D5h,10h,00h,0C0h>, add r16b, al
	expect <0D5h,44h,00h,0F8h>, add al, r31b
	expect <0D5h,10h,80h,0C1h,01h>, add r17l, 1
	expect <0D5h,10h,88h,0E0h>, mov r16b, spl

	; addresses: X4 (index), B4 (base); r20/r28 need a SIB like rsp/r12,
	; r21/r29 a displacement like rbp/r13; 67h and segment prefixes stay
	; before REX2
	expect <0D5h,74h,03h,7Ch,0ACh,08h>, add r31d, [r20+r21*4+8]
	expect <0D5h,18h,83h,00h,01h>, add qword [r16], 1
	expect <0D5h,58h,01h,08h>, add [r16], r17
	expect <0D5h,10h,8Bh,04h,24h>, mov eax, [r20]
	expect <0D5h,10h,8Bh,45h,00h>, mov eax, [r21]
	expect <0D5h,20h,8Bh,04h,0A0h>, mov eax, [rax+r20*4]
	expect <0D5h,11h,8Bh,00h>, mov eax, [r24]
	expect <0D5h,33h,8Bh,04h,2Ch>, mov eax, [r28+r29]
	expect <0D5h,21h,8Bh,44h,2Dh,00h>, mov eax, [r13+r21]
	expect <0D5h,33h,8Bh,84h,0FFh,80h,00h,00h,00h>, mov eax, [r31+r31*8+80h]
	expect <67h,0D5h,10h,8Bh,00h>, mov eax, [r16d]
	expect <67h,0D5h,20h,8Bh,04h,48h>, mov eax, [eax+r17d*2]
	expect <64h,0D5h,10h,8Bh,00h>, mov eax, [fs:r16]
	expect <0D5h,48h,8Dh,05h,00h,00h,00h,00h>, lea r16, [rip]
	expect <0D5h,48h,8Bh,05h,10h,00h,00h,00h>, mov r16, [rip+10h]

	; map 0 and map 1 (M0 = 1 replaces 0Fh); mandatory prefixes before REX2
	expect <0D5h,58h,6Bh,01h,0Ah>, imul r16, [r17], 10
	expect <0D5h,0D8h,0A4h,0C8h,03h>, shld r16, r17, 3
	expect <0D5h,0D8h,44h,0C1h>, cmovz r16, r17
	expect <0D5h,90h,94h,0C0h>, setz r16b
	expect <0D5h,0D0h,0B6h,01h>, movzx r16d, byte [r17]
	expect <0D5h,0D8h,0B1h,08h>, cmpxchg [r16], r17
	expect <0D5h,98h,0BAh,0E0h,05h>, bt r16, 5
	expect <0D5h,10h,0FFh,0D0h>, call r16
	expect <0D5h,10h,0FFh,60h,08h>, jmp qword [r16+8]
	expect <0D5h,90h,22h,0C0h>, mov cr0, r16
	expect <0D5h,90h,21h,0F8h>, mov r16, dr7
	expect <0D5h,10h,8Eh,0C0h>, mov es, r16w	; llvm-mc adds 66h, as for r8w
	expect <0F3h,0D5h,0C8h,0B8h,0C0h>, popcnt r16, rax
	expect <0F3h,0D5h,0D8h,0BDh,04h,24h>, lzcnt r16, [r20]
	expect <66h,0F3h,0D5h,0D5h,0BCh,0FEh>, tzcnt r31w, r30w
	expect <0D5h,98h,0C7h,08h>, cmpxchg16b [r16]

	; x87, MMX, SSE memory and GPR forms
	expect <0D5h,90h,28h,00h>, movaps xmm0, [r16]
	expect <0D5h,90h,0FEh,00h>, paddd mm0, [r16]
	expect <66h,0D5h,98h,6Eh,0C0h>, movq xmm0, r16
	expect <66h,0D5h,90h,7Eh,0F8h>, movd r16d, xmm7
	expect <0D5h,10h,0DDh,00h>, fld qword [r16]
	expect <0D5h,90h,0AEh,00h>, fxsave [r16]

	; register in the opcode (x86.store_operand_prefix)
	expect <0D5h,18h,0C7h,0C0h,01h,00h,00h,00h>, mov r16, 1
	expect <0D5h,10h,0B8h,78h,56h,34h,12h>, mov r16d, 12345678h
	expect <0D5h,18h,0B8h,0ABh,89h,67h,45h,23h,01h,00h,00h>, mov r16, 123456789ABh
	expect <0D5h,10h,0B4h,0FFh>, mov r20b, 0FFh
	expect <0D5h,10h,50h>, push r16
	expect <0D5h,11h,50h>, push r24
	expect <0D5h,11h,5Fh>, pop r31
	expect <66h,0D5h,10h,50h>, pushw r16w
	expect <0D5h,18h,90h>, xchg rax, r16
	expect <0D5h,58h,87h,0C1h>, xchg r16, r17
	expect <0D5h,98h,0C8h>, bswap r16
	expect <0D5h,91h,0C9h>, bswap r25d

	; {rex2} without an extended register
	expect <0D5h,08h,01h,0D8h>, {rex2} add rax, rbx
	expect <0D5h,00h,03h,04h,51h>, {rex2} add eax, [rcx+rdx*2]
	expect <0D5h,00h,50h>, {rex2} push rax
	expect <0D5h,01h,58h>, {rex2} pop r8
	expect <0D5h,80h,0C8h>, {rex2} bswap eax
	expect <0D5h,00h,0B8h,01h,00h,00h,00h>, {rex2} mov eax, 1
	expect <0D5h,80h,28h,00h>, {rex2} movaps xmm0, [rax]
	expect <0F3h,0D5h,80h,0B8h,0C1h>, {rex2} popcnt eax, ecx
	expect <0D5h,00h,0FFh,20h>, {rex2} jmp qword [rax]
	; ... ignored where REX2 is not allowed (Intel 3.1.2.1, not llvm-mc)
	expect <0Fh,38h,0F0h,01h>, {rex2} movbe eax, [rcx]
	expect <0Fh,0AEh,20h>, {rex2} xsave [rax]
	expect <0A8h,01h>, {rex2} test al, 1
	use32
	expect <89h,0C8h>, {rex2} mov eax, ecx
	use64

	; the names are registers of the right class and number
	irp <reg,class,number>, r16b,x86.r8,16, r16l,x86.r8,16, r31b,x86.r8,31, \
				r16w,x86.r16,16, r31w,x86.r16,31, \
				r16d,x86.r32,16, r31d,x86.r32,31, \
				r16,x86.r64,16, r31,x86.r64,31
		assert 1 metadataof reg relativeto class & 1 metadataof reg - class = number
	end irp

else if FAIL = 1	; r16-r31 need APX_F
	use i386, x64
	add rax, r16

else if FAIL = 2	; also for the opcode-register forms
	use i386, x64
	push r16

else if FAIL = 3	; and 64-bit code
	use32
	mov eax, r16d

else if FAIL = 4	; like REX, REX2 turns ah-bh into spl-dil
	mov ah, r16b

else if FAIL = 5	; VEX/EVEX: APX EVEX bits not implemented yet
	vpaddd zmm2, zmm1, [r16]

else if FAIL = 6	; a VEX instruction with no EVEX form is not promoted
	vaesimc xmm0, [r16]

else if FAIL = 7	; GPR in ModRM.reg of a VEX instruction
	vcvtss2si r16d, xmm0

else if FAIL = 8	; XOP
	vpcmov xmm0, xmm1, [r16], xmm2

else if FAIL = 9	; map 2 (0F 38): no REX2, and SSE is not promoted to EVEX
	pshufb xmm0, [r16]

else if FAIL = 10	; map 3 (0F 3A): no REX2, not promoted
	pextrd r16d, xmm0, 1

else if FAIL = 11	; XOP (AMD) is not promoted either
	blcfill r16, rax

else if FAIL = 12	; legacy AES (map 2) is not promoted either
	aesenc xmm0, [r16]

else if FAIL = 13	; XSAVE* #UD with REX2
	xsave [r16]

else if FAIL = 14
	xrstor64 [rax+r20]

else if FAIL = 15	; MPX: no CPU has MPX and APX
	bndmov bnd0, [r16]

else if FAIL = 16
	bndcl bnd0, r16

else if FAIL = 17	; VSIB base (EVEX)
	vpgatherdd zmm0{k1}, [r16+zmm1]

else if FAIL = 18	; MPX [base, index] (AMX's takes r16-r31: apx_vex.asm)
	bndstx [r16,rax], bnd0

else if FAIL = 19	; no 16-bit addressing with extended registers
	mov ax, [r16w]

end if
